"""Protocol fixtures and simulated Android-client flows (no radio needed)."""
import asyncio
from types import SimpleNamespace
import pytest
from meshcorestation.rooms.service import RoomService
from meshcorestation.rooms.server import RoomEndpoint, RoomWorker, room_rx_metadata
from meshcorestation.rooms.wire import Identity, Packet, ack, datagram, decrypt, encrypt, transport_code, u32


def test_firmware_crypto_fixture():
    # Generated by compiling zebbel/MeshCore lib/ed25519 at
    # 286a4506920250e13a6f79220de47ab3dac08af7, not by this codec.
    identity = Identity(bytes(range(32)))
    assert identity.public.hex() == '03a107bff3ce10be1d70dd18e74bc09967e4d6309ba50d5f1ddc8664125531b8'
    peer = bytes.fromhex('29acbae141bccaf0b22e1a94d34d0bc7361e526d0bfe12c89794bc9322966dd7')
    assert identity.secret(peer).hex() == 'f6f92efb32945aff683324a1c984c5001f46aaea513f3453138d740b3a604b7d'
    assert identity.signer.sign(b'MeshcoreStation room protocol').hex() == '89d3aabac4e07cb476716f3ff767697c39deb20bb4b07209ecc0f02bd8581993b1126010ca23d2e69baae3568e31b2332aed1a8753c1b037255ce5779d319201'


@pytest.fixture
def mesh(tmp_path):
    now = [1000]
    service = RoomService(tmp_path/'rooms.db', clock=lambda:now[0])
    room = service.create('Community')
    service.set_password(room,'room-test')
    service.set_enabled(room, True)
    writer, reader = Identity(bytes(range(32))), Identity(bytes(range(32,64)))
    service.grant(room, writer.public.hex(), 'writer')
    service.grant(room, reader.public.hex(), 'reader')
    endpoint = RoomEndpoint(service, room, clock=lambda:now[0])
    return service, room, endpoint, writer, reader, now


def login(endpoint, peer, timestamp=1, since=0, scope=None, password=b'room-test'):
    secret = peer.secret(endpoint.identity.public)
    packet = Packet(7, endpoint.identity.public[:1]+peer.public+encrypt(secret,u32(timestamp)+u32(since)+password),1,0x41,b'\xaa\xbb')
    scopes = [{'scope_key': scope.hex()}] if scope is not None else ()
    responses = endpoint.receive(packet.encode(scope), scopes)
    response = Packet.parse(responses[0])
    assert response.kind == 8  # flooded path return with embedded login result
    assert response.route == (0 if scope is not None else 1)
    assert response.path_code == 0x40 and response.path == b''
    clear = decrypt(secret, response.payload[2:])
    assert clear[:4] == b'\x41\xaa\xbb\x01'
    assert clear[8] == 0  # login success
    # Client returns the path learned from the server's flood response.
    path = datagram(peer, endpoint.identity.public, secret, 8, b'\x41\xcc\xdd\xff'+bytes(4), (0,b''))
    endpoint.receive(path.encode())
    return secret


def test_private_login_posts_push_ack_restart(mesh):
    service, rid, endpoint, writer, reader, now = mesh
    ws = login(endpoint,writer)
    rs = login(endpoint,reader)
    clear = u32(2)+b'\0Hello board'
    outgoing = datagram(writer,endpoint.identity.public,ws,2,clear,(0,b'')).encode()
    reply = Packet.parse(endpoint.receive(outgoing)[0])
    assert reply.kind==3 and reply.payload == ack(clear,writer.public)
    assert len(endpoint.new_posts) == 1 and endpoint.new_posts[0]['text'] == 'Hello board'
    endpoint.new_posts.clear()
    assert endpoint.receive(outgoing)  # retry is acknowledged but not duplicated
    assert endpoint.new_posts == []
    assert len(service.details(rid)['posts']) == 1
    now[0] += 7
    push = Packet.parse(endpoint.next_push())
    data = decrypt(rs,push.payload[2:]).rstrip(b'\0')
    assert data[4] >> 2 == 2 and data[5:9] == writer.public[:4] and data[9:] == b'Hello board'
    assert endpoint.next_push() is None  # wait for ACK
    endpoint.receive(Packet(3,ack(data,reader.public),2).encode())
    assert endpoint.sessions[reader.public.hex()].pending is None
    assert endpoint.next_push() is None
    restored = RoomService(service.path)
    assert restored.identity(rid).public == endpoint.identity.public
    assert len(restored.details(rid)['posts']) == 1
    with pytest.raises(ValueError):
        login(RoomEndpoint(restored,rid),reader)  # replay survives restart


def test_denial_tampering_disable_revocation(mesh):
    service,rid,endpoint,writer,reader,now = mesh
    stranger = Identity.generate()
    with pytest.raises(PermissionError): login(endpoint,stranger,password=b'wrong')
    secret=login(endpoint,reader)
    clear=u32(2)+b'\0not allowed'
    raw=datagram(reader,endpoint.identity.public,secret,2,clear,(0,b'')).encode()
    assert endpoint.receive(raw)==[]
    assert endpoint.receive(raw[:-1]+bytes([raw[-1]^1]))==[]
    assert not service.details(rid)['posts']
    service.revoke(rid,reader.public.hex())
    assert endpoint.receive(raw)==[]
    assert not endpoint.sessions
    service.set_enabled(rid,False)
    assert endpoint.advert() is None
    assert endpoint.receive(raw)==[]


def test_retry_limit_and_keepalive(mesh):
    service,rid,endpoint,writer,reader,now=mesh
    secret=login(endpoint,reader)
    service.local_post(rid,'Announcement')
    now[0]+=7
    for _ in range(3):
        assert endpoint.next_push() is not None
        now[0]+=20
    assert endpoint.next_push() is None
    clear=u32(2)+b'\x02'+u32(0)
    response=Packet.parse(endpoint.receive(datagram(reader,endpoint.identity.public,secret,0,clear,(0,b'')).encode())[0])
    assert response.payload==ack(clear,reader.public)+b'\x01'
    assert endpoint.next_push() is not None


def test_scope_and_malformed_packets(mesh):
    service,rid,endpoint,writer,reader,now=mesh
    scope=bytes(range(16))
    secret=writer.secret(endpoint.identity.public)
    packet=Packet(7,endpoint.identity.public[:1]+writer.public+encrypt(secret,u32(1)+u32(0)+b'\0'))
    with pytest.raises(PermissionError): endpoint.receive(packet.encode())
    with pytest.raises(PermissionError): endpoint.receive(packet.encode(bytes(16)))
    login(endpoint,writer,scope=scope)
    advert=Packet.parse(endpoint.advert())
    assert advert.route==1 and advert.kind==4
    with pytest.raises(ValueError): Packet.parse(b'\x01\xc1x')
    with pytest.raises(ValueError): decrypt(secret,b'\0'*19)
    with pytest.raises(ValueError): Identity.generate().secret(b'\x01'+bytes(31))


def test_worker_failure_isolated_and_stopped(tmp_path):
    from meshcore import EventType
    async def scenario():
        service=RoomService(tmp_path/'rooms.db');rid=service.create('Test');service.set_password(rid,'room-test');service.set_enabled(rid,True)
        sent=[];unsub=[];logs=[]
        async def send(raw,priority):
            sent.append(raw)
            return SimpleNamespace(type=EventType.ERROR)
        mc=SimpleNamespace(commands=SimpleNamespace(send_raw_packet=send),subscribe=lambda *a:'subscription',unsubscribe=unsub.append)
        companion=SimpleNamespace(mc=mc,logger=SimpleNamespace(warning=lambda *a:logs.append(a)))
        worker=RoomWorker(companion,service);worker.start()
        await asyncio.wait_for(worker.task,2)
        assert sent and 'rejected raw packet' in worker.error
        assert not worker.status()['running']
        await worker.close()
        assert unsub==['subscription']
        # Disabled rooms never send a probe, advertisement or any other frame.
        service.set_enabled(rid,False);sent.clear()
        worker=RoomWorker(companion,service);worker.start()
        await asyncio.sleep(.3);await worker.close()
        assert not sent
    asyncio.run(scenario())


def test_password_enrolls_unknown_peer_and_invalidates_sessions(mesh):
    service,rid,endpoint,writer,reader,now=mesh
    stranger=Identity.generate()
    key=stranger.public.hex()
    with pytest.raises(PermissionError): login(endpoint,stranger,password=b'wrong')
    assert key not in {m['public_key'] for m in service.details(rid)['members']}
    login(endpoint,stranger,password=b'room-test')
    assert service.access(rid,key)=='writer'
    assert key in endpoint.sessions
    service.set_password(rid,'new-password')
    assert endpoint.next_push() is None
    assert not endpoint.sessions
    with pytest.raises(PermissionError): login(endpoint,stranger,timestamp=2,password=b'room-test')
    login(endpoint,stranger,timestamp=2,password=b'new-password')
    # Being recorded as a participant never bypasses the password.
    with pytest.raises(PermissionError): login(endpoint,stranger,timestamp=3,password=b'')


@pytest.mark.parametrize('path_code,path,reverse',[(0,b'',b''),(0x42,b'\x11\x22\x33\x44',b'\x33\x44\x11\x22'),(0x82,b'abcdef',b'defabc')])
@pytest.mark.parametrize('scope', [None, bytes(range(16))])
def test_flood_login_returns_flooded_path_with_scope(mesh,path_code,path,reverse,scope):
    service,rid,endpoint,writer,reader,now=mesh
    unknown=Identity.generate()
    secret=unknown.secret(endpoint.identity.public)
    payload=endpoint.identity.public[:1]+unknown.public+encrypt(secret,u32(1)+u32(0)+b'room-test')
    incoming=Packet(7,payload,1,path_code,path).encode(scope)
    known = [{'scope_key': scope.hex()}] if scope is not None else ()
    outgoing=Packet.parse(endpoint.receive(incoming, known)[0])
    assert outgoing.route == (0 if scope is not None else 1)
    assert outgoing.path_code == path_code & 0xC0 and outgoing.path == b''
    assert outgoing.kind==8
    if scope is not None:
        assert int.from_bytes(outgoing.codes[:2], 'little') == transport_code(scope, 8, outgoing.payload)
    clear=decrypt(secret,outgoing.payload[2:])
    assert clear[:1+len(path)]==bytes([path_code])+path
    assert clear[1+len(path)] == 1  # encrypted login result
    assert clear[2+len(path)+4] == 0  # successful login
    assert endpoint.sessions[unknown.public.hex()].path == (path_code, reverse)
    assert 'scope_key' not in service.config(rid)


def test_unknown_scoped_login_falls_back_to_unscoped_flood(mesh):
    service,rid,endpoint,writer,reader,now=mesh
    peer=Identity.generate()
    secret=peer.secret(endpoint.identity.public)
    payload=endpoint.identity.public[:1]+peer.public+encrypt(secret,u32(1)+u32(0)+b'room-test')
    incoming=Packet(7,payload).encode(bytes(range(16)))
    response=Packet.parse(endpoint.receive(incoming, [{'scope_key': 'ff'*16}])[0])
    assert response.kind == 8 and response.route == 1
    assert decrypt(secret,response.payload[2:])[1] == 1


def test_direct_login_response_behavior_unchanged(mesh):
    service,rid,endpoint,writer,reader,now=mesh
    peer=Identity.generate()
    secret=peer.secret(endpoint.identity.public)
    payload=endpoint.identity.public[:1]+peer.public+encrypt(secret,u32(1)+u32(0)+b'room-test')
